/* ============================================================
   AgendaBot :: Helpers comunes (sin dependencias externas)
   Zona horaria fija: America/Bogota (UTC-5, sin horario de verano)
   ============================================================ */
const TZ_OFFSET_MS = -5 * 60 * 60 * 1000;
function pad(n, l) { return String(n).padStart(l, '0'); }
function ahora() { return new Date(Date.now() + TZ_OFFSET_MS); }
function aFechaISO(d) { return d.getUTCFullYear() + '-' + pad(d.getUTCMonth() + 1, 2) + '-' + pad(d.getUTCDate(), 2); }
function aHoraHM(d) { return pad(d.getUTCHours(), 2) + ':' + pad(d.getUTCMinutes(), 2); }
function hoyISO() { return aFechaISO(ahora()); }
function horaActual() { return aHoraHM(ahora()); }
function timestampCO() { const d = ahora(); return aFechaISO(d) + ' ' + aHoraHM(d) + ':' + pad(d.getUTCSeconds(), 2); }
function sumarDias(f, n) {
  const p = String(f).split('-').map(Number);
  return aFechaISO(new Date(Date.UTC(p[0], p[1] - 1, p[2] + n)));
}
function esFechaValida(s) {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(String(s || ''))) return false;
  const p = String(s).split('-').map(Number);
  if (p[1] < 1 || p[1] > 12) return false;
  const diasMes = new Date(Date.UTC(p[0], p[1], 0)).getUTCDate();
  return p[2] >= 1 && p[2] <= diasMes && p[0] >= 2000 && p[0] <= 2100;
}
function esHoraValida(s) { return /^([01]\d|2[0-3]):[0-5]\d$/.test(String(s || '')); }
function esPasado(f, h) {
  const hoy = hoyISO();
  if (f < hoy) return true;
  if (f === hoy && h && h <= horaActual()) return true;
  return false;
}
function vacio(s) { return String(s == null ? '' : s).trim().length === 0; }
function limpiar(s) { return String(s == null ? '' : s).trim().replace(/\s+/g, ' ').slice(0, 200); }
function filasReales(items, clave) {
  return items.map(function (i) { return i.json; })
              .filter(function (r) { return r && r[clave] != null && String(r[clave]).trim() !== ''; });
}
function siguienteId(filas, campo, prefijo) {
  let max = 0;
  for (const r of filas) {
    const m = String(r[campo] || '').match(/(\d+)\s*$/);
    if (m) { const n = parseInt(m[1], 10); if (n > max) max = n; }
  }
  return prefijo + '-' + pad(max + 1, 3);
}
function leerDatos(t) { try { const o = JSON.parse(t || '{}'); return (o && typeof o === 'object') ? o : {}; } catch (e) { return {}; } }
function esVerdadero(v) {
  const s = String(v == null ? '' : v).trim().toUpperCase();
  return s === 'TRUE' || s === 'VERDADERO' || s === 'SI' || s === 'SÍ' || s === '1' || s === 'X' || s === 'YES';
}
const PIE = '\n————————\n9 Volver   ·   /menu Menú principal   ·   /cancelar Cancelar';
function opcionInvalida(extra) {
  return '⚠️ No entendí esa opción.\n' + (extra || 'Escribe únicamente el número de una de las opciones mostradas.');
}
function salida(mensaje, pantalla, paso, datos, resultado, accion, fila) {
  return [{ json: {
    mensaje: String(mensaje).slice(0, 3900),
    pantalla_nueva: pantalla,
    paso_nuevo: String(paso),
    datos_parciales: JSON.stringify(datos || {}),
    resultado: resultado || 'OK',
    accion: accion || 'NINGUNA',
    fila: fila || {}
  }}];
}

/* =====================================================================
   MODULO HABITOS
   Pantallas: HABITOS | HABITOS_NUEVO (4 pasos) | HABITOS_EDITAR (3 pasos)
              HABITOS_ESTADO (2 pasos) | HABITOS_ELIMINAR (2 pasos)
   Hoja: HABITOS(id_habito, nombre, frecuencia, hora_recordatorio, estado)
   NOTA DE DISENO: la hoja HABITOS no tiene columna creado_por, por lo que
   los habitos son compartidos por todos los usuarios del bot.
   ===================================================================== */
const ctx = $('▶️ Entrada Hábitos').first().json;
const filas = filasReales($input.all(), 'id_habito');

const texto = String(ctx.texto || '').trim();
const pantalla = String(ctx.pantalla_actual || 'HABITOS').toUpperCase();
const paso = String(ctx.paso_actual || '0');
const d = leerDatos(ctx.datos_parciales);

const FRECUENCIAS = { '1': 'DIARIO', '2': 'DIAS HABILES', '3': 'SEMANAL', '4': 'MENSUAL' };
const ICONO = { 'ACTIVO': '🟢', 'INACTIVO': '⚪', 'ELIMINADO': '🗑️' };

const MENU =
  '🔁 HÁBITOS\n' +
  'Aquí construyes rutinas y recibes recordatorios de ellas.\n\n' +
  '1  Crear hábito\n' +
  '2  Ver hábitos\n' +
  '3  Editar hábito\n' +
  '4  Activar o desactivar hábito\n' +
  '5  Eliminar hábito\n' +
  '9  Volver al menú principal\n\n' +
  '💡 Recomendado: 2 Ver hábitos\n' +
  'Tip: escribe únicamente el número.';

/* Entrada directa desde el menu principal: se muestra el menu del modulo
   sin consumir el numero que el usuario uso para entrar. */
if (ctx.entrada_modulo === true || String(ctx.entrada_modulo) === 'true')
  return salida(MENU, 'HABITOS', '0', {}, 'MENU_HABITOS');


function vivos() {
  return filas.filter(function (r) {
    return String(r.estado || '').trim().toUpperCase() !== 'ELIMINADO';
  }).sort(function (a, b) { return String(a.id_habito).localeCompare(String(b.id_habito)); });
}

function listado(hs) {
  return hs.map(function (h, i) {
    const e = String(h.estado || '').toUpperCase();
    return (i + 1) + ')  ' + (ICONO[e] || '•') + ' ' + h.nombre +
           '\n      🔁 ' + h.frecuencia + '  ·  ⏰ ' + h.hora_recordatorio +
           '  ·  ' + e + '  ·  ' + h.id_habito;
  }).join('\n');
}

function fila(h, cambios) {
  return {
    id_habito: h.id_habito,
    nombre: (cambios && cambios.nombre) || h.nombre,
    frecuencia: (cambios && cambios.frecuencia) || h.frecuencia,
    hora_recordatorio: (cambios && cambios.hora_recordatorio) || h.hora_recordatorio,
    estado: (cambios && cambios.estado) || h.estado
  };
}

const H1 = '🆕 NUEVO HÁBITO — Paso 1 de 4: NOMBRE\n\n' +
           '¿Qué hábito quieres construir?\n\n' +
           'Ejemplo: Caminar 30 minutos\n\n' +
           '9 Volver   ·   /cancelar Cancelar';
const H2 = '🆕 NUEVO HÁBITO — Paso 2 de 4: FRECUENCIA\n\n' +
           '¿Cada cuánto lo vas a hacer?\n\n' +
           '1  Diario\n2  Días hábiles (lunes a viernes)\n3  Semanal\n4  Mensual\n\n' +
           '💡 Recomendado: 1 Diario\n' +
           '9 Volver   ·   /cancelar Cancelar';
const H3 = '🆕 NUEVO HÁBITO — Paso 3 de 4: HORA DE RECORDATORIO\n\n' +
           '¿A qué hora quieres que te lo recuerde?\n' +
           'Formato HH:MM de 24 horas. Ejemplo: 07:00\n\n' +
           '💡 Recomendado: 07:00\n' +
           '9 Volver   ·   /cancelar Cancelar';

function resumen() {
  return '📋 RESUMEN DEL HÁBITO\n\n' +
         '🔁 Nombre:      ' + d.nombre + '\n' +
         '📆 Frecuencia:  ' + d.frecuencia + '\n' +
         '⏰ Hora:        ' + d.hora + '\n\n' +
         '1  Confirmar y guardar\n2  Editar desde el principio\n3  Cancelar\n\n' +
         '💡 Recomendado: 1 Confirmar y guardar';
}

function pedirSeleccion(hs, verbo, destino) {
  return salida('🔧 ¿Cuál hábito quieres ' + verbo + '?\n\n' + listado(hs) + '\n\n' +
                'Escribe el número del hábito (1 a ' + hs.length + ').\n\n' +
                '💡 Recomendado: 1\n9 Volver   ·   /cancelar Cancelar',
                destino, '1', { opciones: hs.map(function (h) { return h.id_habito; }) },
                'SELECCION_PEDIDA');
}

/* ------------------------------------------------------------------ MENU */
if (pantalla === 'HABITOS') {
  if (texto === '1') return salida(H1, 'HABITOS_NUEVO', '1', {}, 'WIZARD_INICIADO');
  if (texto === '2') {
    const hs = vivos();
    if (hs.length === 0)
      return salida('📭 Todavía no hay hábitos registrados.\n\n' + MENU,
                    'HABITOS', '0', {}, 'CONSULTA_VACIA');
    const act = hs.filter(function (h) { return String(h.estado || '').toUpperCase() === 'ACTIVO'; });
    return salida('🔁 HÁBITOS (' + hs.length + ' · ' + act.length + ' activos)\n\n' +
                  listado(hs.slice(0, 20)) + '\n\n' + MENU, 'HABITOS', '0', {}, 'CONSULTA_OK');
  }
  if (texto === '3' || texto === '4' || texto === '5') {
    const hs = vivos();
    if (hs.length === 0)
      return salida('📭 No hay hábitos registrados todavía.\n\n' + MENU,
                    'HABITOS', '0', {}, 'SIN_HABITOS');
    const cfg = { '3': ['editar', 'HABITOS_EDITAR'],
                  '4': ['activar o desactivar', 'HABITOS_ESTADO'],
                  '5': ['eliminar', 'HABITOS_ELIMINAR'] }[texto];
    return pedirSeleccion(hs, cfg[0], cfg[1]);
  }
  if (texto === '9') return salida('👌 Volvamos al menú principal.\n\nEscribe /menu para verlo.',
                                   'MENU', '0', {}, 'VOLVER');
  return salida(opcionInvalida('En Hábitos espero un número del 1 al 5, o 9 para volver.') +
                '\n\n' + MENU, 'HABITOS', '0', {}, 'OPCION_INVALIDA');
}

/* ----------------------------------------------------------- ALTA */
if (pantalla === 'HABITOS_NUEVO') {
  if (paso === '1') {
    if (texto === '9') return salida(MENU, 'HABITOS', '0', {}, 'VOLVER');
    const n = limpiar(texto);
    if (vacio(n)) return salida('⚠️ El nombre no puede quedar vacío.\n\n' + H1,
                                'HABITOS_NUEVO', '1', d, 'VACIO');
    if (n.length < 3) return salida('⚠️ Ese nombre es muy corto. Usa al menos 3 caracteres.\n\n' + H1,
                                    'HABITOS_NUEVO', '1', d, 'NOMBRE_CORTO');
    const dup = vivos().some(function (h) {
      return String(h.nombre || '').trim().toLowerCase() === n.toLowerCase();
    });
    if (dup) return salida('⚠️ Ya existe un hábito con ese nombre.\n' +
                           'Elige otro nombre para no confundirte.\n\n' + H1,
                           'HABITOS_NUEVO', '1', d, 'NOMBRE_DUPLICADO');
    d.nombre = n;
    return salida('✅ Nombre registrado: ' + d.nombre + '\n\n' + H2,
                  'HABITOS_NUEVO', '2', d, 'PASO_1_OK');
  }
  if (paso === '2') {
    if (texto === '9') return salida(H1, 'HABITOS_NUEVO', '1', d, 'VOLVER_PASO');
    const f = FRECUENCIAS[texto];
    if (!f) return salida(opcionInvalida('Para la frecuencia espero 1, 2, 3 o 4.') + '\n\n' + H2,
                          'HABITOS_NUEVO', '2', d, 'FRECUENCIA_INVALIDA');
    d.frecuencia = f;
    return salida('✅ Frecuencia registrada: ' + d.frecuencia + '\n\n' + H3,
                  'HABITOS_NUEVO', '3', d, 'PASO_2_OK');
  }
  if (paso === '3') {
    if (texto === '9') return salida(H2, 'HABITOS_NUEVO', '2', d, 'VOLVER_PASO');
    if (!esHoraValida(texto))
      return salida('⚠️ Formato de hora incorrecto. Debe ser HH:MM, por ejemplo 07:00.\n\n' + H3,
                    'HABITOS_NUEVO', '3', d, 'HORA_INVALIDA');
    d.hora = texto;
    return salida('✅ Hora registrada: ' + d.hora + '\n\n' + resumen(),
                  'HABITOS_NUEVO', '4', d, 'PASO_3_OK');
  }
  if (paso === '4') {
    if (texto === '2' || texto === '9')
      return salida('✏️ Empecemos de nuevo.\n\n' + H1, 'HABITOS_NUEVO', '1', {}, 'EDITAR');
    if (texto === '3')
      return salida('🗑️ Descarté el hábito. No guardé nada.\n\n' + MENU, 'HABITOS', '0', {}, 'CANCELADO');
    if (texto !== '1')
      return salida(opcionInvalida('Aquí espero 1, 2 o 3.') + '\n\n' + resumen(),
                    'HABITOS_NUEVO', '4', d, 'OPCION_INVALIDA');
    if (!d.nombre || !d.frecuencia || !d.hora)
      return salida('⚠️ Faltan datos. Repetimos el proceso.\n\n' + H1,
                    'HABITOS_NUEVO', '1', {}, 'DATOS_INCOMPLETOS');
    const id = siguienteId(filas, 'id_habito', 'HAB');
    const f = { id_habito: id, nombre: d.nombre, frecuencia: d.frecuencia,
                hora_recordatorio: d.hora, estado: 'ACTIVO' };
    return salida('🎉 Hábito creado correctamente.\n\n🆔 ' + id + '\n🔁 ' + f.nombre +
                  '\n📆 ' + f.frecuencia + '\n⏰ ' + f.hora_recordatorio + '\n🟢 ACTIVO\n\n' + MENU,
                  'HABITOS', '0', {}, 'HABITO_CREADO:' + id, 'CREAR', f);
  }
  return salida(H1, 'HABITOS_NUEVO', '1', {}, 'PASO_DESCONOCIDO');
}

/* ------------------------------------------- EDITAR / ESTADO / ELIMINAR */
if (pantalla === 'HABITOS_EDITAR' || pantalla === 'HABITOS_ESTADO' || pantalla === 'HABITOS_ELIMINAR') {
  if (texto === '9') return salida(MENU, 'HABITOS', '0', {}, 'VOLVER');
  const ids = Array.isArray(d.opciones) ? d.opciones : [];

  if (paso === '1') {
    const n = parseInt(texto, 10);
    if (!/^\d+$/.test(texto) || isNaN(n) || n < 1 || n > ids.length)
      return salida(opcionInvalida('Escribe un número entre 1 y ' + ids.length + '.'),
                    pantalla, '1', d, 'SELECCION_INVALIDA');
    const h = filas.find(function (r) { return String(r.id_habito) === String(ids[n - 1]); });
    if (!h) return salida('⚠️ No encontré ese hábito.\n\n' + MENU, 'HABITOS', '0', {}, 'NO_ENCONTRADO');
    d.id_habito = h.id_habito;

    if (pantalla === 'HABITOS_ELIMINAR') {
      return salida('🗑️ ¿Seguro que quieres eliminar este hábito?\n\n' +
                    '🔁 ' + h.nombre + '\n📆 ' + h.frecuencia + '\n⏰ ' + h.hora_recordatorio + '\n\n' +
                    '1  Sí, eliminar\n2  No, conservarlo\n\n' +
                    '💡 Recomendado: 2 No, conservarlo',
                    'HABITOS_ELIMINAR', '2', d, 'CONFIRMACION_PEDIDA');
    }
    if (pantalla === 'HABITOS_ESTADO') {
      return salida('🔄 Hábito: ' + h.nombre + '\nEstado actual: ' + h.estado + '\n\n' +
                    '¿Qué quieres hacer?\n\n1  🟢 Activar\n2  ⚪ Desactivar\n\n' +
                    '💡 Recomendado: ' + (String(h.estado).toUpperCase() === 'ACTIVO' ? '2 Desactivar' : '1 Activar') +
                    '\n9 Volver   ·   /cancelar Cancelar',
                    'HABITOS_ESTADO', '2', d, 'ACCION_PEDIDA');
    }
    return salida('✏️ Hábito: ' + h.nombre + '\n\n¿Qué campo quieres cambiar?\n\n' +
                  '1  Nombre        (actual: ' + h.nombre + ')\n' +
                  '2  Frecuencia    (actual: ' + h.frecuencia + ')\n' +
                  '3  Hora          (actual: ' + h.hora_recordatorio + ')\n\n' +
                  '💡 Recomendado: 3 Hora\n9 Volver   ·   /cancelar Cancelar',
                  'HABITOS_EDITAR', '2', d, 'CAMPO_PEDIDO');
  }

  const h = filas.find(function (r) { return String(r.id_habito) === String(d.id_habito); });
  if (!h) return salida('⚠️ No encontré ese hábito.\n\n' + MENU, 'HABITOS', '0', {}, 'NO_ENCONTRADO');

  if (pantalla === 'HABITOS_ELIMINAR' && paso === '2') {
    if (texto === '2') return salida('👌 No eliminé nada.\n\n' + MENU, 'HABITOS', '0', {}, 'ELIMINACION_ABORTADA');
    if (texto !== '1') return salida(opcionInvalida('Espero 1 (sí) o 2 (no).'),
                                     'HABITOS_ELIMINAR', '2', d, 'OPCION_INVALIDA');
    return salida('🗑️ Hábito eliminado.\n\n🆔 ' + h.id_habito + '\n🔁 ' + h.nombre +
                  '\n\nEl registro se conserva marcado como ELIMINADO para no perder el historial.\n\n' + MENU,
                  'HABITOS', '0', {}, 'HABITO_ELIMINADO:' + h.id_habito,
                  'ACTUALIZAR', fila(h, { estado: 'ELIMINADO' }));
  }

  if (pantalla === 'HABITOS_ESTADO' && paso === '2') {
    const e = { '1': 'ACTIVO', '2': 'INACTIVO' }[texto];
    if (!e) return salida(opcionInvalida('Espero 1 (activar) o 2 (desactivar).'),
                          'HABITOS_ESTADO', '2', d, 'OPCION_INVALIDA');
    return salida('✅ Hábito ' + (e === 'ACTIVO' ? 'activado 🟢' : 'desactivado ⚪') + '.\n\n' +
                  '🆔 ' + h.id_habito + '\n🔁 ' + h.nombre + '\nAntes: ' + h.estado + '\nAhora: ' + e + '\n\n' + MENU,
                  'HABITOS', '0', {}, 'HABITO_' + e + ':' + h.id_habito,
                  'ACTUALIZAR', fila(h, { estado: e }));
  }

  if (pantalla === 'HABITOS_EDITAR' && paso === '2') {
    const campos = { '1': 'nombre', '2': 'frecuencia', '3': 'hora_recordatorio' };
    const c = campos[texto];
    if (!c) return salida(opcionInvalida('Espero 1, 2 o 3.'), 'HABITOS_EDITAR', '2', d, 'OPCION_INVALIDA');
    d.campo = c;
    if (c === 'frecuencia')
      return salida('📆 Elige la nueva frecuencia:\n\n1  Diario\n2  Días hábiles\n3  Semanal\n4  Mensual\n\n' +
                    '💡 Recomendado: 1 Diario\n9 Volver', 'HABITOS_EDITAR', '3', d, 'VALOR_PEDIDO');
    if (c === 'hora_recordatorio')
      return salida('⏰ Escribe la nueva hora en formato HH:MM.\n\nEjemplo: 07:00\n\n' +
                    '💡 Recomendado: 07:00\n9 Volver', 'HABITOS_EDITAR', '3', d, 'VALOR_PEDIDO');
    return salida('✏️ Escribe el nuevo nombre del hábito.\n\nActual: ' + h.nombre + '\n\n9 Volver',
                  'HABITOS_EDITAR', '3', d, 'VALOR_PEDIDO');
  }

  if (pantalla === 'HABITOS_EDITAR' && paso === '3') {
    const c = d.campo;
    let valor = limpiar(texto);
    if (c === 'frecuencia') {
      valor = FRECUENCIAS[texto];
      if (!valor) return salida(opcionInvalida('Espero 1, 2, 3 o 4.'),
                                'HABITOS_EDITAR', '3', d, 'VALOR_INVALIDO');
    } else if (c === 'hora_recordatorio') {
      if (!esHoraValida(texto)) return salida('⚠️ Formato de hora incorrecto. Usa HH:MM, por ejemplo 07:00.',
                                              'HABITOS_EDITAR', '3', d, 'VALOR_INVALIDO');
    } else {
      if (vacio(valor) || valor.length < 3)
        return salida('⚠️ El nombre debe tener al menos 3 caracteres.',
                      'HABITOS_EDITAR', '3', d, 'VALOR_INVALIDO');
    }
    const cambios = {}; cambios[c] = valor;
    return salida('✅ Hábito actualizado.\n\n🆔 ' + h.id_habito + '\nCampo: ' + c +
                  '\nAntes: ' + h[c] + '\nAhora: ' + valor + '\n\n' + MENU,
                  'HABITOS', '0', {}, 'HABITO_EDITADO:' + h.id_habito + '/' + c,
                  'ACTUALIZAR', fila(h, cambios));
  }

  return salida(MENU, 'HABITOS', '0', {}, 'PASO_DESCONOCIDO');
}

return salida(MENU, 'HABITOS', '0', {}, 'PANTALLA_DESCONOCIDA');

const r = $('🧠 Lógica de Hábitos').first().json;
return [{ json: {
  mensaje: r.mensaje, pantalla_nueva: r.pantalla_nueva, paso_nuevo: r.paso_nuevo,
  datos_parciales: r.datos_parciales, resultado: r.resultado
}}];
